import sys
a,b=int(sys.argv[1]),int(sys.argv[2])
def n(c): return f"NVL(TO_CHAR({c},'TM9'),'')"
def d(c,f='YYYY-MM-DD HH24:MI:SS'): return f"NVL(TO_CHAR({c},'{f}'),'')"
def t(c): return f"REPLACE(REPLACE(NVL({c},''),'|',' '),'~',' ')"
cols=[t('T_TYPE'),t('PRODUCT_CODE'),t('ORGANIZATION_NO'),n('STORE_ID'),t('TRANSACTION_NO'),d('TRANSACTION_DATE'),t('STATUS'),n('RECEIVE_STORE_ID'),t('COST_CENTET_NO'),n('PRIMARY_UNIT_COST'),n('LINE_QTY'),t('UOM_CODE'),n('UOM_FACTOR'),t('POSTED_BY'),d('POST_DATE'),t('SUPPLIER_NO'),n('ITEM_DISCOUNT'),n('INVOICE_DISCOUNT'),t('STOCK_ACCOUNT'),t('BATCH_NO'),d('EXPIRY_DATE','YYYY-MM-DD')]
s="||'|'||".join(cols)
print(f"SELECT g, LISTAGG(s,'~') WITHIN GROUP (ORDER BY n) c, RPAD('.',50,'.') p FROM (SELECT n, FLOOR((n-1)/20) g, s FROM (SELECT ROW_NUMBER() OVER (ORDER BY TRANSACTION_DATE, TRANSACTION_NO, T_TYPE, PRODUCT_CODE, BATCH_NO, LINE_QTY, PRIMARY_UNIT_COST, EXPIRY_DATE) n, {s} s FROM EXSYS.IM_PRODUCTS_TRANSACTIONS WHERE TRANSACTION_DATE >= DATE '2026-01-01' AND STATUS IN ('P','C','O'))) WHERE g BETWEEN {a} AND {b} GROUP BY g ORDER BY g")
